CREATE OR REPLACE FUNCTION calculate_rcp(p_vehicle_reg VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_dist_done NUMERIC;
    v_dist_left NUMERIC;
BEGIN
    SELECT distdonekm, distleftkm INTO v_dist_done, v_dist_left
    FROM transportinfo
    WHERE vehiclereg = p_vehicle_reg;

    RETURN (v_dist_done / (v_dist_done + v_dist_left)) * 100;
END;
$$ LANGUAGE plpgsql;
